solution.code:
export const red = {
  transitGateway: { id: "tgw-hub", tablaRutas: "tgw-rtb-principal" },
  attachments: [
    { id: "att-vpc-app", vpc: "vpc-app", tabla: "tgw-rtb-principal" },
    { id: "att-vpc-datos", vpc: "vpc-datos", tabla: "tgw-rtb-principal" },
  ],
  vpcs: [
    {
      id: "vpc-app",
      cidr: "10.0.0.0/16",
      rutas: [
        { destino: "10.0.0.0/16", objetivo: "local" },
        { destino: "10.1.0.0/16", objetivo: "tgw-hub" },
      ],
    },
    {
      id: "vpc-datos",
      cidr: "10.1.0.0/16",
      rutas: [
        { destino: "10.1.0.0/16", objetivo: "local" },
        { destino: "10.0.0.0/16", objetivo: "tgw-hub" },
      ],
    },
  ],
};

spec.code:
const datos = red.vpcs.find((v) => v.id === "vpc-datos");
assert.ok(datos, "debe existir vpc-datos");
assert.ok(datos.rutas.some((r) => r.destino === "10.0.0.0/16" && r.objetivo === red.transitGateway.id), "falta la ruta hacia el transit gateway en vpc-datos");

for (const vpc of red.vpcs) {
  const rutasTgw = vpc.rutas.filter((r) => r.objetivo === red.transitGateway.id);
  assert.strictEqual(rutasTgw.length, 1, vpc.id + " debe tener una sola ruta hacia el transit gateway");
}

const app = red.vpcs.find((v) => v.id === "vpc-app");
const datos = red.vpcs.find((v) => v.id === "vpc-datos");
assert.ok(app.rutas.some((r) => r.destino === "10.0.0.0/16" && r.objetivo === "local"));
assert.ok(app.rutas.some((r) => r.destino === "10.1.0.0/16" && r.objetivo === "tgw-hub"));
assert.ok(datos.rutas.some((r) => r.destino === "10.1.0.0/16" && r.objetivo === "local"));

